from __future__ import annotations

# =============================================================================
# Code_Details_Lab.py
# Person-level NHANES laboratory catalog (same contract as Code_Details_Diet).
# File maps, PDF-parsed rows, purposes, and codebook kinds/codes live here.
#
# Grain is person (one row / SEQN) for public individual-sample files.
# Pooled dioxin/PFC files are registered separately (grain="pool") and should
# NOT be concatenated onto person tables.
#
# Scope: clinical chemistry, fasting glucose/insulin, hormones, thyroid,
# vitamins, iron, pregnancy, PSA, STIs in these books, and the environmental
# urine/blood families (phthalates, phytoestrogens, PAHs, PFAS, VOC metabolites).
# Jackknife replicate weights WTSPH01–52 are generated, not hand-listed.
# =============================================================================

