def _var(
    short,
    sas,
    kind,
    text,
    target,
    codes=None,
    sas_by_cycle=None,
    codes_by_cycle=None,
    label=None,
    notes=None,
    raw_codes=None,
    raw_codes_by_cycle=None,
    target_by_cycle=None,
    definition=None,
    definition_by_cycle=None,
    tables=None,
    day_pair=None,
    unit=None,
    group=None,
    si_pair=None,
    lod_pair=None,
    aliases=None,
):
    return {
        "short": short,
        "sas": sas,
        "kind": kind,
        "text": text,
        "label": label or text,
        "target": target,
        "codes": None if codes is None else dict(codes),
        "sas_by_cycle": dict(sas_by_cycle or {}),
        "codes_by_cycle": dict(codes_by_cycle or {}),
        "notes": notes or "",
        "raw_codes": None if raw_codes is None else dict(raw_codes),
        "raw_codes_by_cycle": dict(raw_codes_by_cycle or {}),
        "target_by_cycle": dict(target_by_cycle or {}),
        "definition": definition or "",
        "definition_by_cycle": dict(definition_by_cycle or {}),
        "tables": tables or ("lab",),
        "day_pair": day_pair,
        "unit": unit or "",
        "group": group or "",
        "si_pair": si_pair,
        "lod_pair": lod_pair,
        "aliases": list(aliases or []),
    }


LAB_VARS: dict = {}


def _add(spec: dict) -> None:
    LAB_VARS[spec["short"]] = spec


