def _add_jackknife(prefix: str, n: int, label: str) -> None:
    for i in range(1, n + 1):
        sas = f"{prefix}{i:02d}"
        short = f"wt_jk_{prefix.lower()}_{i:02d}"
        _add(_var(
            short, sas, "weight",
            f"{label} jackknife replicate {i:02d}.",
            T_6_150,
            notes="Replicate weight for variance estimation on early phthalate files. Prefer SDMVSTRA/SDMVPSU + subsample weight for most analyses.",
            group="weights_jackknife",
        ))


_add_jackknife("WTSPH", 52, "Phthalate MEC")
_add_jackknife("WTSHM", 52, "Urine metals MEC")
_add_jackknife("WTSPO", 52, "Dioxin / PCB MEC")
_add_jackknife("WTSPP", 52, "Current-use pesticide MEC")


# ----- standard biochemistry (BIOPRO / LAB18 / L40) ------------------------

def _chem(short, sas, si_sas, label, unit, si_unit, extra="", target=T_12_150):
    _add(_var(
        short, sas, "continuous",
        f"{label} ({unit}).",
        target,
        unit=unit,
        si_pair=si_sas,
        notes=(
            "Standard biochemistry profile (LAB18 / L40_* / BIOPRO_*). "
            "Random (non-fasting) draw unless the person was in the AM fasting session. "
            "Do not treat BIOPRO glucose/triglycerides as fasting values. "
            + extra
        ).strip(),
        definition=f"Serum {label.lower()}, conventional units.",
        group="biochemistry",
    ))
    if si_sas:
        _add(_var(
            short + "_si", si_sas, "continuous",
            f"{label} ({si_unit}).",
            target,
            unit=si_unit,
            notes="SI companion of " + sas + ".",
            definition=f"Serum {label.lower()}, SI units.",
            group="biochemistry",
        ))


