PHTHALATES = [
    ("mbp", "URXMBP", "Mono-n-butyl phthalate", "ng/mL"),
    ("mcp", "URXMCP", "Mono-cyclohexyl phthalate", "ng/mL"),
    ("mep", "URXMEP", "Mono-ethyl phthalate", "ng/mL"),
    ("mhp", "URXMHP", "Mono-(2-ethylhexyl) phthalate (MEHP)", "ng/mL"),
    ("mnp", "URXMNP", "Mono-isononyl phthalate", "ng/mL"),
    ("mop", "URXMOP", "Mono-n-octyl phthalate", "ng/mL"),
    ("mzp", "URXMZP", "Mono-benzyl phthalate", "ng/mL"),
    ("cnp", "URXCNP", "Mono(carboxynonyl) phthalate", "ng/mL"),
    ("cop", "URXCOP", "Mono(carboxyoctyl) phthalate", "ng/mL"),
    ("ecp", "URXECP", "Mono-2-ethyl-5-carboxypentyl phthalate", "ng/mL"),
    ("hibp", "URXHIBP", "Mono-2-hydroxy-iso-butyl phthalate", "ng/mL"),
    ("mbp_mibp", "URXMIB", "Mono-isobutyl phthalate", "ng/mL"),
    ("mhhp", "URXMHH", "Mono-(2-ethyl-5-hydroxyhexyl) phthalate", "ng/mL"),
    ("mohp", "URXMOH", "Mono-(2-ethyl-5-oxohexyl) phthalate", "ng/mL"),
    ("mchp", "URXMCH", "Mono-3-carboxypropyl phthalate", "ng/mL"),
]

for slug, sas, label, unit in PHTHALATES:
    _add(_var(
        slug, sas, "continuous",
        f"{label} ({unit}).",
        T_6_150,
        unit=unit,
        lod_pair=sas.replace("URX", "URD") + "LC",
        notes=(
            "Urinary phthalate monoester, isotope-dilution LC-MS/MS after glucuronide deconjugation. "
            "99-00/01-02 lived on PHPYPA with phytoestrogens and a thin PAH panel; "
            "03-04+ split to L24PH_C / PHTHTE_*. "
            "Five early metabolites (MEP, MZP, MOP, MNP, MCP) had impure standards — "
            "NCHS applied a correction factor to released values. "
            "Values below LOD are filled with LOD/sqrt(2). "
            "Use subsample weights (WTSPH2YR or WTSB2YR). Creatinine-adjust with URXUCR."
        ),
        definition=f"Spot urine {label}.",
        group="phthalates",
    ))
    lc = sas.replace("URX", "URD") + "LC"
    _add(_var(
        slug + "_lod", lc, "flag",
        f"{label} comment code.",
        T_6_150,
        codes=LOD_COMMENT,
        notes="1 = result was below the LOD; the URX* value is LOD/sqrt(2).",
        group="phthalates",
    ))


