_PDF_CODE_SETS = {
    "LOD": LOD_COMMENT,
}

def _pretty_short(short: str, sas: str) -> str:
    """Replace a colliding '..._lbxcrp' suffix with a readable qualifier."""
    sas_u = str(sas).upper()
    low = str(sas).lower()
    if not short.endswith("_" + low):
        return short
    base = short[: -(len(low) + 1)]
    if sas_u.startswith("LB2") or sas_u.startswith("UR2"):
        tag = "exam2"
    elif sas_u.startswith("ORX"):
        tag = "oral"
    elif sas_u.startswith("LBDR"):
        tag = "linear_array"
    elif sas_u.startswith("SS"):
        tag = "surplus"
    elif sas_u.startswith("UR"):
        tag = None if "urine" in base else "urine"
    elif sas_u.startswith("LBD") and sas_u.endswith("SI"):
        tag = "si"
    else:
        tag = None
    if tag:
        cand = f"{base}_{tag}"
        if cand not in LAB_VARS:
            return cand
    if base not in LAB_VARS:
        return base
    return short


def _short_from_label(label: str, sas: str) -> str:
    import re
    t = re.sub(r"\([^)]*\)", " ", label or sas)
    t = t.lower().replace("comment code", "lod").replace("&", " and ").replace("+", " and ")
    t = re.sub(r"[^a-z0-9]+", "_", t)
    t = re.sub(r"_+", "_", t).strip("_")
    for tail in ("result", "results", "value", "values"):
        if t.endswith("_" + tail):
            t = t[: -(len(tail) + 1)]
    parts = t.split("_")[:8]
    t = "_".join(p for p in parts if p)
    if not t or t == sas.lower() or len(t) < 3:
        return sas.lower()
    # Cut on a token boundary so a word is never left as _compoun / _compou.
    if len(t) > 48:
        cut = t[:48]
        if "_" in cut:
            cut = cut.rsplit("_", 1)[0]
        t = cut or t[:48]
    t = t.rstrip("_")
    if t.endswith("_compoun") or t.endswith("_compou"):
        t = t[: t.rfind("_")] + "_compound"
    return t


def _load_pdf_vars() -> None:
    existing_sas = {str(spec.get("sas") or "").upper() for spec in LAB_VARS.values()}
    for spec in LAB_VARS.values():
        for alias in (spec.get("sas_by_cycle") or {}).values():
            if alias:
                existing_sas.add(str(alias).upper())
        for alias in spec.get("aliases") or []:
            existing_sas.add(str(alias).upper())
        if spec.get("si_pair"):
            existing_sas.add(str(spec["si_pair"]).upper())
        if spec.get("lod_pair"):
            existing_sas.add(str(spec["lod_pair"]).upper())
    for prefix, n in LAB_PDF_JACKKNIFE_PREFIXES.items():
        if any(s.startswith(prefix.lower()) or s.startswith("wt_jk_" + prefix.lower())
               for s in LAB_VARS):
            continue
        _add_jackknife(prefix, n, f"{prefix} MEC")
        for i in range(1, n + 1):
            existing_sas.add(f"{prefix}{i:02d}")
    for row in LAB_PDF_VARS:
        if len(row) == 8:
            short, sas, kind, label, target, unit, group, codes_key = row
            notes = f"{label}."
            codes = _PDF_CODE_SETS.get(codes_key)
        else:
            short, sas, kind, label, target, unit, group, notes, codes = row
            if isinstance(codes, str):
                codes = _PDF_CODE_SETS.get(codes)
        if codes:
            norm = {}
            for k, v in dict(codes).items():
                try:
                    if isinstance(k, str) and k.isdigit():
                        k = int(k)
                    elif isinstance(k, float) and k.is_integer():
                        k = int(k)
                except (TypeError, ValueError):
                    pass
                norm[k] = v
            codes = norm
        if str(sas).upper() in existing_sas:
            continue
        sas_u = str(sas).upper()
        if short == str(sas).lower() and label:
            short = _short_from_label(label, sas)
        if sas_u.startswith(("LB2", "UR2")) and not short.endswith("_exam2"):
            short = f"{short}_exam2"
        if short in LAB_VARS:
            short = _pretty_short(f"{short}_{str(sas).lower()}", sas)
        if short in LAB_VARS:
            short = f"{short}_{str(sas).lower()}"
        text = label if str(label).endswith(".") else f"{label}."
        _add(_var(
            short, sas, kind,
            text,
            target or T_ALL,
            codes=codes or None,
            label=label,
            unit=unit,
            group=group or "lab_pdf",
            notes=notes or text,
            definition=label,
        ))
        existing_sas.add(str(sas).upper())
    # If a collision suffix was added but the plain name is free, drop the suffix.
    for short, spec in list(LAB_VARS.items()):
        sas = str(spec.get("sas") or "")
        if not sas or not short.endswith("_" + sas.lower()):
            continue
        base = short[: -(len(sas) + 1)]
        pretty = _pretty_short(short, sas)
        new = pretty if pretty not in LAB_VARS else (base if base not in LAB_VARS else None)
        if not new or new == short or new in LAB_VARS:
            continue
        LAB_VARS.pop(short)
        spec["short"] = new
        LAB_VARS[new] = spec


_load_pdf_vars()


def _repair_truncated_shorts() -> None:
    """Finish short names cut off mid-word as _compoun / _compou."""
    for short, spec in list(LAB_VARS.items()):
        if short.endswith("_compoun") or short.endswith("_compou"):
            fixed = short[: short.rfind("_")] + "_compound"
        else:
            continue
        new = fixed
        i = 2
        while new in LAB_VARS and new != short:
            new = f"{fixed}_{i}"
            i += 1
        if new == short:
            continue
        LAB_VARS.pop(short)
        spec["short"] = new
        LAB_VARS[new] = spec


_repair_truncated_shorts()

