def _hint_for(spec: dict) -> str:
    blob = " ".join(str(spec.get(k) or "") for k in ("short", "sas", "label", "text")).lower()
    for keys, hint in _CLINICAL_HINTS:
        if all(k.lower() in blob for k in keys):
            return hint
    return ""


def _purpose_for(spec: dict) -> str:
    group = spec.get("group") or ""
    if group in LAB_PDF_PURPOSES:
        return LAB_PDF_PURPOSES[group]
    g = group.replace("_surplus", "")
    for key, para in LAB_PDF_PURPOSES.items():
        if group and (group in key or key in group or g and g in key):
            return para
    return ""


def _looks_stub_note(notes: str) -> bool:
    n = notes or ""
    return (
        n.startswith("Registered from")
        or "lab_combined codebook" in n
        or n.startswith("Coded result")
        or ". Reported in " in n
        or ". Coded result; see codes." in n
    )


def _enrich_lab_specs() -> None:
    for spec in LAB_VARS.values():
        label = (spec.get("label") or spec.get("text") or spec["short"]).rstrip(".")
        codes = spec.get("codes") or {}
        code_vals = {str(v).lower() for v in codes.values()}
        if spec["kind"] == "continuous" and code_vals and not any(
            "limit of detection" in v or "below limit" in v or "and over" in v for v in code_vals
        ):
            if code_vals <= {"positive", "negative", "indeterminate", "inadequate", "invalid", "yes", "no"} \
                    or {"positive", "negative"} <= code_vals:
                spec["kind"] = "categorical"
        purpose = _purpose_for(spec)
        hint = _hint_for(spec)
        if spec["kind"] in {"id", "weight"} and not _looks_stub_note(spec.get("notes") or ""):
            continue
        if not _looks_stub_note(spec.get("notes") or "") and spec.get("group") not in {
            "", "lab_pdf"
        } and "Registered" not in (spec.get("notes") or ""):
            # keep curated write-ups unless they are stubs
            if purpose and len(spec.get("notes") or "") > 80:
                continue
        parts = []
        if purpose:
            sent = purpose.split(". ")[0].rstrip(".")
            if len(sent) > 220:
                sent = sent[:217].rstrip() + "..."
            parts.append(sent)
        if hint:
            parts.append(hint.rstrip("."))
        elif spec.get("unit"):
            parts.append(f"Units: {spec['unit']}")
        if spec["kind"] == "categorical" and codes:
            parts.append("Coded field")
        note = ". ".join(p for p in parts if p) + "."
        note = " ".join(note.split())
        if len(note) > 420:
            note = note[:417].rstrip() + "..."
        spec["notes"] = note
        if not spec.get("definition"):
            spec["definition"] = label


def _coerce_code_map(codes: dict | None) -> dict | None:
    if not codes:
        return None
    out = {}
    for k, v in dict(codes).items():
        nk = k
        try:
            if isinstance(k, str) and k.replace(".", "", 1).isdigit():
                f = float(k)
                nk = int(f) if f.is_integer() else f
            elif isinstance(k, float) and k.is_integer():
                nk = int(k)
        except (TypeError, ValueError):
            nk = k
        out[nk] = v
    return out


def _apply_codebook_kinds() -> None:
    """Prefer codebook frequency tables over the coarse PDF-row kind."""
    by_sas = {}
    for spec in LAB_VARS.values():
        sas = str(spec.get("sas") or "").upper()
        if sas:
            by_sas[sas] = spec
        for alias in spec.get("aliases") or []:
            by_sas[str(alias).upper()] = spec
    for sas, rec in LAB_CODEBOOK_KINDS.items():
        spec = by_sas.get(str(sas).upper())
        if spec is None:
            continue
        codes = _coerce_code_map(rec.get("codes"))
        raw = _coerce_code_map(rec.get("raw_codes"))
        kind = rec.get("kind")
        if kind == "categorical":
            spec["kind"] = "categorical"
            if codes:
                spec["codes"] = codes
        elif raw:
            spec["raw_codes"] = raw
        label = (spec.get("label") or spec.get("text") or "").lower()
        if spec["kind"] != "categorical" and (
            str(spec.get("sas") or "").upper().endswith("LC") or "comment code" in label
        ):
            spec["kind"] = "categorical"
            spec["codes"] = spec.get("codes") or LOD_COMMENT


_apply_codebook_kinds()
_enrich_lab_specs()

