# =============================================================================
# Lookups (same contract as the diet catalog)
# =============================================================================

def sas_name(spec: dict, cycle: str | None = None, day: int = 1) -> str:
    if cycle and cycle in spec["sas_by_cycle"]:
        return spec["sas_by_cycle"][cycle]
    return spec["sas"]


def codes_for(spec: dict, cycle: str | None = None) -> dict | None:
    if cycle and cycle in spec["codes_by_cycle"]:
        return spec["codes_by_cycle"][cycle]
    return spec["codes"]


def raw_codes_for(spec: dict, cycle: str | None = None) -> dict | None:
    raw_by = spec.get("raw_codes_by_cycle") or {}
    if cycle and cycle in raw_by:
        return raw_by[cycle]
    if spec.get("raw_codes"):
        return spec["raw_codes"]
    return codes_for(spec, cycle)


def kind_for(spec: dict, cycle: str | None = None) -> str:
    return spec["kind"]


def target_for(spec: dict, cycle: str | None = None) -> str:
    tgt_by = spec.get("target_by_cycle") or {}
    if cycle and cycle in tgt_by:
        return tgt_by[cycle]
    return spec["target"]


def definition_for(spec: dict, cycle: str | None = None) -> str:
    def_by = spec.get("definition_by_cycle") or {}
    if cycle and cycle in def_by:
        return def_by[cycle]
    return spec.get("definition") or ""


def notes_for(spec: dict) -> str:
    return spec.get("notes") or ""


def lab_table(cycle: str, panel: str) -> str | None:
    """panel is a key of LAB_FILES (biopro, fasting_glucose, phthalates, ...)."""
    files = LAB_FILES.get(panel) or {}
    return files.get(cycle)


def _index_sas(index: dict, sas: str | None, short: str) -> None:
    if sas:
        index[str(sas)] = short
        index[str(sas).upper()] = short
        index[str(sas).lower()] = short


SAS_TO_SHORT_LAB: dict = {}
for spec in LAB_VARS.values():
    _index_sas(SAS_TO_SHORT_LAB, spec.get("sas"), spec["short"])
    for alias in (spec.get("sas_by_cycle") or {}).values():
        _index_sas(SAS_TO_SHORT_LAB, alias, spec["short"])
    _index_sas(SAS_TO_SHORT_LAB, spec.get("day_pair"), spec["short"])
    for alias in spec.get("aliases") or []:
        _index_sas(SAS_TO_SHORT_LAB, alias, spec["short"])
    if spec.get("si_pair"):
        _index_sas(SAS_TO_SHORT_LAB, spec["si_pair"], spec["short"] + "_si")
    if spec.get("lod_pair"):
        _index_sas(SAS_TO_SHORT_LAB, spec["lod_pair"], spec["short"] + "_lod")


def coalesce_sas_aliases(df, sas_to_short: dict | None = None):
    """Fold leftover SAS aliases into the short name after a multi-cycle concat."""
    lookup = sas_to_short or SAS_TO_SHORT_LAB
    out = df.copy()
    for col in list(out.columns):
        short = lookup.get(str(col)) or lookup.get(str(col).upper())
        if not short or short == col:
            continue
        if short not in out.columns:
            out.rename(columns={col: short}, inplace=True)
            continue
        out[short] = out[short].where(out[short].notna(), out[col])
        out.drop(columns=[col], inplace=True)
    return out


# Standalone panel → names dictionary (short names; SAS in the 2nd list)
def _names_in_group(group: str) -> dict:
    shorts, sases = [], []
    for spec in LAB_VARS.values():
        if spec.get("group") == group:
            shorts.append(spec["short"])
            sases.append(spec["sas"])
    return {"short": shorts, "sas": sases}


LAB_GROUPS = {
    group: _names_in_group(group)
    for group in sorted({spec.get("group") or "lab" for spec in LAB_VARS.values()})
}

