def lab_replicate_columns() -> list[str]:
    """SAS + short names for lab jackknife replicate weights (WTSPH01–52, …)."""
    names: list[str] = []
    for spec in LAB_VARS.values():
        if spec.get("group") != "weights_jackknife":
            continue
        if spec.get("sas"):
            names.append(str(spec["sas"]))
        names.append(str(spec["short"]))
        for alias in spec.get("aliases") or []:
            names.append(str(alias))
    return names


LAB_REPLICATE_COLUMNS = lab_replicate_columns()